import numpy as np, math
c=3e8; f=2.4e9; n=3.0; d0=1.0; tx=20.0; minr=-75.0
PL0=20*math.log10(4*math.pi*d0*f/c)
def rssi(d):
    if d<=0: return tx
    return tx-(PL0+10*n*math.log10(d/d0))
aps=[(50.0,100.0),(150.0,100.0)]
def assoc(p):
    best=None;bs=-1e9
    for i,a in enumerate(aps):
        d=math.hypot(p[0]-a[0],p[1]-a[1]); r=rssi(d)
        if r>=minr and r>bs: bs=r;best=i
    return best

def trace(start,steps,seed=42,W=200.0,H=200.0,smin=1.0,smax=5.0,order='target_first',snap=True):
    rng=np.random.RandomState(seed)
    def nt():
        if order=='target_first':
            x=rng.uniform(0,W); y=rng.uniform(0,H); s=rng.uniform(smin,smax)
        else:
            s=rng.uniform(smin,smax); x=rng.uniform(0,W); y=rng.uniform(0,H)
        return np.array([x,y]),s
    pos=np.array(start,dtype=float)
    tgt,spd=nt()
    out=[]
    for _ in range(steps):
        d=tgt-pos; dist=math.hypot(d[0],d[1])
        if dist<=spd:
            pos=tgt.copy(); tgt,spd=nt()
        else:
            pos=pos+d/dist*spd
        out.append((pos[0],pos[1]))
    return out

def analyze(tr):
    a=[assoc(p) for p in tr]
    ho_strict=sum(1 for i in range(1,len(a)) if a[i] is not None and a[i-1] is not None and a[i]!=a[i-1])
    ho_any=sum(1 for i in range(1,len(a)) if a[i]!=a[i-1])
    ho_reassoc=sum(1 for i in range(1,len(a)) if a[i] is not None and a[i]!=a[i-1])
    cov=sum(1 for x in a if x is not None)
    return ho_strict,ho_any,ho_reassoc,cov,len(a),100.0*cov/len(a)

for start in [(100.0,100.0),(0.0,0.0),(50.0,100.0),(10.0,10.0)]:
  for order in ['target_first','speed_first']:
    tr=trace(start,500,order=order)
    print(start,order,analyze(tr))
"

