import numpy as np, math, collections
c=3e8; f=2.4e9; n=3.0; d0=1.0; tx=20.0
PL0=20*math.log10(4*math.pi*d0*f/c)
R=10**((tx+75.0-PL0)/(10*n))
aps=[(50.,100.),(150.,100.)]
def assoc(p):
    b=None;bd=1e18
    for i,a in enumerate(aps):
        d=math.hypot(p[0]-a[0],p[1]-a[1])
        if d<=R and d<bd: bd=d;b=i
    return b
def run(order,start,mode,steps=500,seed=42,W=200.,H=200.,smin=1.,smax=5.):
    rng=np.random.RandomState(seed)
    def nt():
        if order=='tf': x=rng.uniform(0,W);y=rng.uniform(0,H);s=rng.uniform(smin,smax)
        else: s=rng.uniform(smin,smax);x=rng.uniform(0,W);y=rng.uniform(0,H)
        return np.array([x,y]),s
    pos=np.array(start,float); tgt,spd=nt(); out=[]
    for _ in range(steps):
        if mode=='snap':
            d=tgt-pos; dist=math.hypot(*d)
            if dist<=spd: pos=tgt.copy(); tgt,spd=nt()
            else: pos=pos+d/dist*spd
        elif mode=='eps':
            d=tgt-pos; dist=math.hypot(*d)
            if dist<1e-9: tgt,spd=nt(); d=tgt-pos; dist=math.hypot(*d)
            step=min(spd,dist); pos=pos+d/dist*step
            if math.hypot(*(tgt-pos))<1e-9: tgt,spd=nt()
        elif mode=='carry':
            rem=spd
            while rem>1e-12:
                d=tgt-pos; dist=math.hypot(*d)
                if dist<=rem: pos=tgt.copy(); rem-=dist; tgt,spd=nt()
                else: pos=pos+d/dist*rem; rem=0.
        out.append((pos[0],pos[1]))
    return out
def an(tr):
    a=[assoc(p) for p in tr]
    s=sum(1 for i in range(1,len(a)) if a[i] is not None and a[i-1] is not None and a[i]!=a[i-1])
    cov=sum(1 for x in a if x is not None)
    return s, round(100.*cov/len(a),2)
ho=collections.Counter(); cv=collections.Counter()
for order in ['tf','sf']:
 for start in [(100.,100.),(0.,0.),(50.,100.),(150.,100.),(10.,10.),(100.,0.),(1.,1.),(0.,100.)]:
  for mode in ['snap','eps','carry']:
    r=an(run(order,start,mode)); ho[r[0]]+=1; cv[r[1]]+=1
print('R=%.4f'%R)
print('handover:',sorted(ho.items()))
print('coverage:',sorted(cv.items()))
print()
print('CANONICAL tf/(100,100)/snap:',an(run('tf',(100.,100.),'snap')))
# uniform-area geometric coverage
xs=np.linspace(0,200,4001); ys=np.linspace(0,200,4001)
X,Y=np.meshgrid(xs,ys)
m=((X-50)**2+(Y-100)**2<=R*R)|((X-150)**2+(Y-100)**2<=R*R)
print('uniform-area covered fraction = %.4f%%'%(100*m.mean()))
